sys_variable_value.value:
(function execute(inputs, outputs) {


        if (new sn_hr_core.hr_PdfUtils().isValidPdfTemplateForPreFill(inputs.templateid)) {
          //inputs.taskId, inputs.taskTable ,inputs.templateId, inputs.generatedPdfName
          var   pdfDraftSysId = new sn_hr_core.hr_PdfUtils().prefillPdfTemplate(inputs.templateid, false, inputs.recordid, inputs.recordtable, inputs.recordid);
            if (gs.nil(pdfDraftSysId)) {
                 outputs.pdfattachmentid =0;
            }
          else
            outputs.pdfattachmentid = pdfDraftSysId;
        } 

})(inputs, outputs);

